import Avatar, { type AvatarProps } from '@mui/material/Avatar';
import Box from '@mui/material/Box';
import { useDefaultProps } from '@mui/material/DefaultPropsProvider';
import type { SxProps, Theme } from '@mui/material/styles';
import { mergeSx } from 'merge-sx';
import type { ReactNode } from 'react';

const contentSx: SxProps<Theme> = {
  display: 'inline-flex',
  alignItems: 'center',
  verticalAlign: 'middle',
  gap: '6px',
  minWidth: 0,
  maxWidth: '100%',
};
const avatarSx: SxProps<Theme> = {
  order: -1,
  width: '16px',
  height: '16px',
  fontSize: '10px',
};

export function SelectOptionContent({
  label,
  avatar,
}: {
  label: ReactNode;
  avatar: AvatarProps;
}) {
  const defaults = useDefaultProps<AvatarProps>({
    props: {},
    name: 'MuiAvatar',
  });
  return (
    <Box component="span" className="SvSelect-optionContent" sx={contentSx}>
      {/* MUI typeahead reads DOM text; keep the label before decorative initials. */}
      <Box
        component="span"
        sx={{ minWidth: 0, overflow: 'hidden', textOverflow: 'ellipsis' }}
      >
        {label}
      </Box>
      <Avatar
        component="span"
        aria-hidden
        {...avatar}
        sx={mergeSx(avatarSx, defaults.sx, avatar.sx)}
      />
    </Box>
  );
}
